window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-ccca43818c31748e"]={"versions": [{"id": "FIG-ccca43818c31748e", "releases": ["R17-03_R1.1.0"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Zustandsübergangsdiagramm (State Machine Diagram) zur Modellierung des Prozess-Lebenszyklus (Process Lifecycle) innerhalb der AUTOSAR Adaptive Platform, spezifiziert im Modul Execution Management (SWS ExecutionManagement). Das Diagramm definiert die linearen Zustandsphasen eines Betriebssystemprozesses von der Bereitstellung bis zur Beendigung.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Diagramm umfasst fünf aufeinanderfolgende Zustände:</p>\n<ul class=\"fig-list\"><li><code>Idle</code>: Ruhezustand des Prozesses vor Ausführung.\n</li><li><code>Starting</code>: Startphase des Prozesses.\n</li><li><code>Running</code>: Aktiver Ausführungszustand.\n</li><li><code>Terminating</code>: Beendigungsphase des Prozesses.\n</li><li><code>Terminated</code>: Endzustand nach Beendigung.\n</li></ul>\n<p class=\"fig-p\">Verbindungselemente und Transitionen zwischen den Zuständen:</p>\n<ul class=\"fig-list\"><li>Übergang <code>Idle</code> -&gt; <code>Starting</code>: Beschriftet mit Aktion/Trigger <code>Execute</code>.\n</li><li>Übergang <code>Starting</code> -&gt; <code>Running</code>: Beschriftet mit Aktion/Trigger <code>Schedule</code>.\n</li><li>Übergang <code>Running</code> -&gt; <code>Terminating</code>: Beschriftet mit Aktion/Trigger <code>Terminate</code>.\n</li><li>Übergang <code>Terminating</code> -&gt; <code>Terminated</code>: Beschriftet mit Ereignis/Aktion <code>Resource free</code>.\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Der Ablauf erfolgt strikt sequenziell und unidirektional über fünf diskrete Phasen:</p>\n<ol class=\"fig-list\"><li>Ein inaktiver Prozess befindet sich in <code>Idle</code>.\n</li><li>Durch den Aufruf oder Trigger <code>Execute</code> wechselt der Prozess von <code>Idle</code> nach <code>Starting</code>.\n</li><li>Sobald der Prozess lauffähig vorbereitet ist, führt der Übergang <code>Schedule</code> in den Zustand <code>Running</code>.\n</li><li>Aus dem laufenden Betrieb leitet der Trigger <code>Terminate</code> den Übergang in die Phase <code>Terminating</code> ein.\n</li><li>Nach Freigabe aller Ressourcen (<code>Resource free</code>) geht der Prozess in den Endzustand <code>Terminated</code> über.\n</li></ol>\n<p class=\"fig-p\">Es sind keine Verzweigungen, Rückführungen oder Fehlerpfade modelliert.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Normative Vorgabe für das Execution Management zur Steuerung von Adaptive Applications:</p>\n<ul class=\"fig-list\"><li>Die Lebenszyklusphasen eines Prozesses müssen die definierten Zustände sequenziell durchlaufen.\n</li><li>Die Ausführung eines Prozesses setzt den Zustand <code>Idle</code> voraus.\n</li><li>Das Execution Management steuert die Prozessinstanziierung über <code>Execute</code>, übergibt den Prozess über <code>Schedule</code> an den OS-Scheduler und erzwingt das Herunterfahren über <code>Terminate</code>.\n</li><li>Der Übergang nach <code>Terminated</code> erfordert den Abschluss der Ressourcenfreigabe (<code>Resource free</code>).\n</li></ul>", "model": "gemini-3.8-flash (via agy)"}, {"id": "FIG-0ff21b7770bfe5c1", "releases": ["R17-10_R1.2.0"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Zustandsübergangsdiagramm (State Machine Diagram) zur Modellierung des Prozess-Lebenszyklus (Process Lifecycle) innerhalb der AUTOSAR Adaptive Platform, spezifiziert im Modul Execution Management (SWS ExecutionManagement). Das Diagramm definiert die linearen Zustandsphasen eines Betriebssystemprozesses von der Bereitstellung bis zur Beendigung.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Diagramm ist in einen umfassenden Rahmen mit grauem Hintergrund eingebettet und enthält fünf Zustände mit Zustandserläuterungen:</p>\n<ul class=\"fig-list\"><li><code>Idle</code>: Zustand mit erläuternder Bedingung <code>(Application Manifest references FG1:State2)</code>.\n</li><li><code>Starting</code>: Zustand mit interner Aktionsbeschreibung <code>process created, resources allocated</code>.\n</li><li><code>Running</code>: Aktiver Zustand des Prozesses.\n</li><li><code>Terminating</code>: Phase der kontrollierten Prozessbeendigung.\n</li><li><code>Terminated</code>: Endzustand mit interner Aktionsbeschreibung <code>process resources freed</code>.\n</li></ul>\n<p class=\"fig-p\">Die Zustandsübergänge werden als Blockpfeile dargestellt:</p>\n<ul class=\"fig-list\"><li><code>Idle</code> -&gt; <code>Starting</code>: Beschriftet mit <code>Execute</code>.\n</li><li><code>Starting</code> -&gt; <code>Running</code>: Beschriftet mit <code>Schedule</code>.\n</li><li><code>Running</code> -&gt; <code>Terminating</code>: Beschriftet mit <code>Terminate</code>.\n</li><li><code>Terminating</code> -&gt; <code>Terminated</code>: Unbeschrifteter Blockpfeil.\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Sequenzieller Ablauf des Prozess-Lebenszyklus:</p>\n<ol class=\"fig-list\"><li><code>Idle</code>: Der Prozess verharrt im Ruhezustand, solange das zugehörige Application Manifest eine bestimmte Funktionsgruppe und einen Zustand referenziert (<code>FG1:State2</code>).\n</li><li><code>Execute</code>: Initiiert den Übergang nach <code>Starting</code>.\n</li><li><code>Starting</code>: Der Betriebssystemprozess wird erzeugt und Betriebsmittel werden zugewiesen (<code>process created, resources allocated</code>).\n</li><li><code>Schedule</code>: Schaltet den initialisierten Prozess in den Zustand <code>Running</code>.\n</li><li><code>Terminate</code>: Leitet das Beenden des Prozesses ein und führt in <code>Terminating</code>.\n</li><li>Nach Abschluss der Terminierung geht der Prozess über einen unbeschrifteten Übergang in <code>Terminated</code> über, wobei die Prozessressourcen freigegeben werden (<code>process resources freed</code>).\n</li></ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Entwicklungs- und Integrationshinweise für das Execution Management:</p>\n<ul class=\"fig-list\"><li>Die Aktivierung eines Prozesses aus <code>Idle</code> ist an die Konfiguration im Application Manifest gebunden, spezifisch an die Zuordnung zu Funktionsgruppen und deren Zuständen (exemplarisch <code>FG1:State2</code>).\n</li><li>Beim Übergang in bzw. während <code>Starting</code> müssen Prozessinstanzen erzeugt und deren benötigte Systemressourcen allokiert sein, bevor <code>Schedule</code> den Prozess zur Ausführung freigibt.\n</li><li>Im Zustand <code>Terminated</code> müssen alle vom Prozess belegten Ressourcen vollständig freigegeben sein (<code>process resources freed</code>).\n</li></ul>", "model": "gemini-3.8-flash (via agy)"}, {"id": "FIG-ddb6b33310e4d158", "releases": ["R18-03_R1.4.0"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Zustandsübergangsdiagramm (State Machine Diagram) zur Modellierung des Prozess-Lebenszyklus (Process Lifecycle) innerhalb der AUTOSAR Adaptive Platform, spezifiziert im Modul Execution Management (SWS ExecutionManagement). Das Diagramm definiert die linearen Zustandsphasen eines Betriebssystemprozesses von der Bereitstellung bis zur Beendigung.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Diagramm umfasst fünf Hauptzustände in einem umrahmten Bereich:</p>\n<ul class=\"fig-list\"><li><code>Idle</code>: Ruhezustand ohne Zusatzbedingungen.\n</li><li><code>Starting</code>: Zustand mit interner Beschreibung <code>process created, resources allocated</code>.\n</li><li><code>Running</code>: Zustand der Prozessausführung.\n</li><li><code>Terminating</code>: Zustand des geregelten Prozessstopps.\n</li><li><code>Terminated</code>: Zustand nach Prozessende mit interner Beschreibung <code>process resources freed</code>.\n</li></ul>\n<p class=\"fig-p\">Transitionskanten:</p>\n<ul class=\"fig-list\"><li><code>Idle</code> -&gt; <code>Starting</code>: Blockpfeil mit Beschriftung <code>Execute</code>.\n</li><li><code>Starting</code> -&gt; <code>Running</code>: Blockpfeil mit Beschriftung <code>Schedule</code>.\n</li><li><code>Running</code> -&gt; <code>Terminating</code>: Blockpfeil mit Beschriftung <code>Terminate</code>.\n</li><li><code>Terminating</code> -&gt; <code>Terminated</code>: Unbeschrifteter Blockpfeil.\n</li><li><code>Terminated</code> -&gt; <code>Idle</code>: Pfeillinie als Rückführungsschleife von der Unterkante von <code>Terminated</code> zur Unterkante von <code>Idle</code>.\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Zyklischer Ablauf des Prozess-Lebenszyklus:</p>\n<ol class=\"fig-list\"><li>Aus <code>Idle</code> führt <code>Execute</code> in die Erzeugungsphase <code>Starting</code> (<code>process created, resources allocated</code>).\n</li><li><code>Schedule</code> überführt den Prozess in <code>Running</code>.\n</li><li><code>Terminate</code> versetzt den laufenden Prozess in <code>Terminating</code>.\n</li><li>Der Prozess wechselt in <code>Terminated</code>, worin die zugewiesenen Ressourcen freigegeben werden (<code>process resources freed</code>).\n</li><li>Über eine Rückführungskante gelangt der beendete Prozess aus <code>Terminated</code> wieder in den Ausgangszustand <code>Idle</code> zurück, sodass ein erneuter Lebenszyklusdurchlauf möglich ist.\n</li></ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Normative Relevanz für das Execution Management:</p>\n<ul class=\"fig-list\"><li>Prozesse sind nach Erreichen des Zustands <code>Terminated</code> und erfolgter Ressourcenfreigabe rezyklierbar und kehren in den Zustand <code>Idle</code> zurück.\n</li><li>Eine Prozessinstanz kann nach Beendigung für spätere Aktivierungen erneut gestartet werden, ohne dass eine Neukonfiguration erforderlich ist.\n</li><li>Der Zustand <code>Idle</code> ist generisch und nicht fest an eine spezifische Funktionsgruppen-Zustandsreferenz gebunden dargestellt.\n</li></ul>", "model": "gemini-3.8-flash (via agy)"}, {"id": "FIG-37317d5af8ec94ad", "releases": ["R18-10-1", "R18-10_R4.4.0_R1.5.0", "R19-03"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Zustandsübergangsdiagramm (State Machine Diagram) zur Modellierung des Prozess-Lebenszyklus (Process Lifecycle) innerhalb der AUTOSAR Adaptive Platform, spezifiziert im Modul Execution Management (SWS ExecutionManagement). Das Diagramm definiert die linearen Zustandsphasen eines Betriebssystemprozesses von der Bereitstellung bis zur Beendigung.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Diagramm umfasst fünf Hauptzustände in einem umrahmten Bereich:</p>\n<ul class=\"fig-list\"><li><code>Idle</code>: Ruhezustand des Prozesses.\n</li><li><code>Starting</code>: Erzeugungsphase mit interner Angabe <code>process created, resources allocated</code>.\n</li><li><code>Running</code>: Ausführungszustand.\n</li><li><code>Terminating</code>: Beendigungsphase.\n</li><li><code>Terminated</code>: Endzustand mit interner Angabe <code>process resources freed</code>.\n</li></ul>\n<p class=\"fig-p\">Transitionskanten:</p>\n<ul class=\"fig-list\"><li><code>Idle</code> -&gt; <code>Starting</code>: Blockpfeil mit Beschriftung <code>Execute</code>.\n</li><li><code>Starting</code> -&gt; <code>Running</code>: Blockpfeil mit Beschriftung <code>Schedule</code>.\n</li><li><code>Running</code> -&gt; <code>Terminating</code>: Blockpfeil mit Beschriftung <code>Terminate</code>.\n</li><li><code>Terminating</code> -&gt; <code>Terminated</code>: Unbeschrifteter Blockpfeil.\n</li></ul>\n<p class=\"fig-p\">Es gibt keine Rückführungskante von <code>Terminated</code> nach <code>Idle</code>.</p>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Ablauf als lineare Kette:</p>\n<ol class=\"fig-list\"><li>Der Prozess startet in <code>Idle</code>.\n</li><li>Über den Trigger <code>Execute</code> wechselt der Prozess nach <code>Starting</code>, wo die Prozesserstellung und die Zuweisung von Ressourcen stattfinden (<code>process created, resources allocated</code>).\n</li><li><code>Schedule</code> überführt den Prozess in den Zustand <code>Running</code>.\n</li><li>Aus <code>Running</code> führt der Trigger <code>Terminate</code> in den Zustand <code>Terminating</code>.\n</li><li>Nach der Terminierung wechselt der Prozess in <code>Terminated</code>, in dem sämtliche Prozessressourcen freigegeben werden (<code>process resources freed</code>).\n</li></ol>\n<p class=\"fig-p\">Der Lebenszyklus endet in <code>Terminated</code>; es existiert kein Übergang zurück nach <code>Idle</code>.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Normative Festlegungen für Implementierung und Systemdesign:</p>\n<ul class=\"fig-list\"><li>Der Lebenszyklus einer Prozessinstanz ist linear terminiert: Ein terminierter Prozess (<code>Terminated</code>) kehrt nicht mehr in <code>Idle</code> zurück.\n</li><li>Soll eine Anwendung nach Erreichen von <code>Terminated</code> erneut gestartet werden, muss das Execution Management eine neue Prozessinstanz erzeugen, anstatt einen bestehenden Prozesszustand wiederzuverwenden.\n</li><li>Die vollständige Freigabe aller Ressourcen (<code>process resources freed</code>) ist zwingender Bestandteil des Abschlusses im Zustand <code>Terminated</code>.\n</li></ul>", "model": "gemini-3.8-flash (via agy)"}, {"id": "FIG-83f744d5c65e2e09", "releases": ["R19-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Zustandsübergangsdiagramm (State Machine Diagram) zur Modellierung des Prozess-Lebenszyklus (Process Lifecycle) innerhalb der AUTOSAR Adaptive Platform, spezifiziert im Modul Execution Management (SWS ExecutionManagement). Das Diagramm definiert die linearen Zustandsphasen eines Betriebssystemprozesses von der Bereitstellung bis zur Beendigung.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Diagramm umfasst fünf Hauptzustände in einem umrahmten Bereich:</p>\n<ul class=\"fig-list\"><li><code>Idle</code>: Ruhezustand des Prozesses.\n</li><li><code>Starting</code>: Erzeugungsphase mit interner Angabe <code>process created, resources allocated</code>.\n</li><li><code>Running</code>: Ausführungszustand.\n</li><li><code>Terminating</code>: Beendigungsphase.\n</li><li><code>Terminated</code>: Endzustand mit interner Angabe <code>process resources freed</code>.\n</li></ul>\n<p class=\"fig-p\">Transitionskanten:</p>\n<ul class=\"fig-list\"><li><code>Idle</code> -&gt; <code>Starting</code>: Blockpfeil mit Beschriftung <code>Execute</code>.\n</li><li><code>Starting</code> -&gt; <code>Running</code>: Blockpfeil mit Beschriftung <code>Schedule</code>.\n</li><li><code>Running</code> -&gt; <code>Terminating</code>: Blockpfeil mit Beschriftung <code>Terminate</code>.\n</li><li><code>Terminating</code> -&gt; <code>Terminated</code>: Unbeschrifteter Blockpfeil.\n</li></ul>\n<p class=\"fig-p\">Es gibt keine Rückführungskante von <code>Terminated</code> nach <code>Idle</code>.</p>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Ablauf als lineare Kette:</p>\n<ol class=\"fig-list\"><li>Der Prozess startet in <code>Idle</code>.\n</li><li>Über den Trigger <code>Execute</code> wechselt der Prozess nach <code>Starting</code>, wo die Prozesserstellung und die Zuweisung von Ressourcen stattfinden (<code>process created, resources allocated</code>).\n</li><li><code>Schedule</code> überführt den Prozess in den Zustand <code>Running</code>.\n</li><li>Aus <code>Running</code> führt der Trigger <code>Terminate</code> in den Zustand <code>Terminating</code>.\n</li><li>Nach der Terminierung wechselt der Prozess in <code>Terminated</code>, in dem sämtliche Prozessressourcen freigegeben werden (<code>process resources freed</code>).\n</li></ol>\n<p class=\"fig-p\">Der Lebenszyklus endet in <code>Terminated</code>; es existiert kein Übergang zurück nach <code>Idle</code>.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Normative Festlegungen für Implementierung und Systemdesign:</p>\n<ul class=\"fig-list\"><li>Der Lebenszyklus einer Prozessinstanz ist linear terminiert: Ein terminierter Prozess (<code>Terminated</code>) kehrt nicht mehr in <code>Idle</code> zurück.\n</li><li>Soll eine Anwendung nach Erreichen von <code>Terminated</code> erneut gestartet werden, muss das Execution Management eine neue Prozessinstanz erzeugen, anstatt einen bestehenden Prozesszustand wiederzuverwenden.\n</li><li>Die vollständige Freigabe aller Ressourcen (<code>process resources freed</code>) ist zwingender Bestandteil des Abschlusses im Zustand <code>Terminated</code>.\n</li></ul>", "model": "gemini-3.8-flash (via agy)"}, {"id": "FIG-aec6019ca08781b6", "releases": ["R25-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Zustandsübergangsdiagramm (State Machine Diagram) zur Modellierung des Prozess-Lebenszyklus (Process Lifecycle) innerhalb der AUTOSAR Adaptive Platform, spezifiziert im Modul Execution Management (SWS ExecutionManagement). Das Diagramm definiert die linearen Zustandsphasen eines Betriebssystemprozesses von der Bereitstellung bis zur Beendigung.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Diagramm umfasst fünf Hauptzustände in einem umrahmten Bereich:</p>\n<ul class=\"fig-list\"><li><code>Idle</code>: Ruhezustand des Prozesses.\n</li><li><code>Starting</code>: Erzeugungsphase mit interner Angabe <code>process created, resources allocated</code>.\n</li><li><code>Running</code>: Ausführungszustand.\n</li><li><code>Terminating</code>: Beendigungsphase.\n</li><li><code>Terminated</code>: Endzustand mit interner Angabe <code>process resources freed</code>.\n</li></ul>\n<p class=\"fig-p\">Transitionskanten:</p>\n<ul class=\"fig-list\"><li><code>Idle</code> -&gt; <code>Starting</code>: Blockpfeil mit Beschriftung <code>Execute</code>.\n</li><li><code>Starting</code> -&gt; <code>Running</code>: Blockpfeil mit Beschriftung <code>Schedule</code>.\n</li><li><code>Running</code> -&gt; <code>Terminating</code>: Blockpfeil mit Beschriftung <code>Terminate</code>.\n</li><li><code>Terminating</code> -&gt; <code>Terminated</code>: Unbeschrifteter Blockpfeil.\n</li></ul>\n<p class=\"fig-p\">Es gibt keine Rückführungskante von <code>Terminated</code> nach <code>Idle</code>.</p>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Ablauf als lineare Kette:</p>\n<ol class=\"fig-list\"><li>Der Prozess startet in <code>Idle</code>.\n</li><li>Über den Trigger <code>Execute</code> wechselt der Prozess nach <code>Starting</code>, wo die Prozesserstellung und die Zuweisung von Ressourcen stattfinden (<code>process created, resources allocated</code>).\n</li><li><code>Schedule</code> überführt den Prozess in den Zustand <code>Running</code>.\n</li><li>Aus <code>Running</code> führt der Trigger <code>Terminate</code> in den Zustand <code>Terminating</code>.\n</li><li>Nach der Terminierung wechselt der Prozess in <code>Terminated</code>, in dem sämtliche Prozessressourcen freigegeben werden (<code>process resources freed</code>).\n</li></ol>\n<p class=\"fig-p\">Der Lebenszyklus endet in <code>Terminated</code>; es existiert kein Übergang zurück nach <code>Idle</code>.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Normative Festlegungen für Implementierung und Systemdesign:</p>\n<ul class=\"fig-list\"><li>Der Lebenszyklus einer Prozessinstanz ist linear terminiert: Ein terminierter Prozess (<code>Terminated</code>) kehrt nicht mehr in <code>Idle</code> zurück.\n</li><li>Soll eine Anwendung nach Erreichen von <code>Terminated</code> erneut gestartet werden, muss das Execution Management eine neue Prozessinstanz erzeugen, anstatt einen bestehenden Prozesszustand wiederzuverwenden.\n</li><li>Die vollständige Freigabe aller Ressourcen (<code>process resources freed</code>) ist zwingender Bestandteil des Abschlusses im Zustand <code>Terminated</code>.\n</li></ul>", "model": "gemini-3.8-flash (via agy)"}], "trans": [{"from": "FIG-ccca43818c31748e", "to": "FIG-0ff21b7770bfe5c1", "fr": "R17-03_R1.1.0", "tr": "R17-10_R1.2.0", "change": "redaktionell", "label": "redaktionell", "html": "<ul class=\"fig-list\"><li>Das Gesamtdiagramm erhält einen umrahmenden Außenrahmen mit grau hinterlegter Diagrammfläche.\n</li><li>Im Zustand <code>Idle</code> wird der erklärende Zusatz <code>(Application Manifest references FG1:State2)</code> ergänzt.\n</li><li>Im Zustand <code>Starting</code> wird die Erläuterung <code>process created, resources allocated</code> ergänzt.\n</li><li>Im Zustand <code>Terminated</code> wird die Erläuterung <code>process resources freed</code> ergänzt (vorher als Pfeilbeschriftung <code>Resource free</code> am Übergang von <code>Terminating</code> nach <code>Terminated</code> platziert).\n</li><li>Die Beschriftung des Übergangspfeils von <code>Terminating</code> nach <code>Terminated</code> entfällt.\n</li><li>Die Typografie der Zustandsnamen wurde auf halbfette Schrift umgestellt.\n</li></ul>"}, {"from": "FIG-0ff21b7770bfe5c1", "to": "FIG-ddb6b33310e4d158", "fr": "R17-10_R1.2.0", "tr": "R18-03_R1.4.0", "change": "normativ", "label": "normative Änderung", "html": "<ul class=\"fig-list\"><li>Zustand <code>Idle</code>: Der Klammerzusatz <code>(Application Manifest references FG1:State2)</code> entfällt.\n</li><li>Es wird eine Rückführungs-Transitionskante vom Zustand <code>Terminated</code> zurück zum Zustand <code>Idle</code> eingefügt (ermöglicht die erneute Ausführung terminierter Prozesse im Lebenszyklus).\n</li></ul>"}, {"from": "FIG-ddb6b33310e4d158", "to": "FIG-37317d5af8ec94ad", "fr": "R18-03_R1.4.0", "tr": "R18-10-1", "change": "normativ", "label": "normative Änderung", "html": "<ul class=\"fig-list\"><li>Die Rückführungs-Transitionskante vom Zustand <code>Terminated</code> zurück zum Zustand <code>Idle</code> entfällt vollständig. Der Prozesslebenszyklus endet damit wieder als lineare Kette im Zustand <code>Terminated</code>.\n</li></ul>"}, {"from": "FIG-37317d5af8ec94ad", "to": "FIG-83f744d5c65e2e09", "fr": "R19-03", "tr": "R19-11", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}, {"from": "FIG-83f744d5c65e2e09", "to": "FIG-aec6019ca08781b6", "fr": "R19-11", "tr": "R25-11", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}]};
